interface Iterator<T> {
  hasNext(): boolean;
  next(): T;
}

class ListIterator<T> implements Iterator<T> {
  private index = 0;
  constructor(private items: T[]) {}
  hasNext() { return this.index < this.items.length; }
  next() { return this.items[this.index++]; }
}

const iter = new ListIterator([1,2,3]);

class ProductCollection {
  private items: Product[] = [];
  private cursor = 0; // shared traversal state

  add(p: Product) { this.items.push(p); }
  getIterator() { return this; } // returns collection as iterator
  hasNext() { return this.cursor < this.items.length; }
  next() { return this.items[this.cursor++]; }
}

const c = new ProductCollection();

class ArrayIterator<T> {
  private i = 0;
  constructor(private items: T[]) {}
  hasNext() { return this.i < this.items.length; }
  next() { return this.items[this.i++]; }
}

class ProductCollection {
  private items: Product[] = [];

